    "lifeStory": "自然博物馆里巴掌大的毛茸茸塔兰托毒蛛看着像大怪兽，其实它的毒液对人类只跟普通蜜蜂蜇一下差不多！它真正的防身绝活藏在圆肚皮上——要是狐狸好奇把鼻子凑过去闻，它就用后腿飞快踢肚子，扬起一片带微型倒钩的毒刚毛，像魔术贴小钩子一样扎得对方直打喷嚏！隔着饲养箱观察它时，别拍玻璃吓唬这位害羞的大毛球哦！",
